using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);

// Load CSV data
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
IDataView dataView = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
    dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string to boolean Label, then build features and train
var pipeline = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnLabel>(
        (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
        contractName: null)
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        "RegionEncoded",
        nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(dataView);

app.MapPost("/predict", (CustomerInput input) =>
{
    var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerDataRaw, ChurnPrediction>(model);
    var row = new CustomerDataRaw
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory,
        Churned = ""
    };
    var prediction = predictionEngine.Predict(row);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability,
        Score = prediction.Score
    });
});

app.MapGet("/", () => "Churn Predictor API. POST to /predict with { age, income, region, purchaseHistory }.");
app.Run();

